package io.github.foodjournal.infrastructure.gemini;
import io.github.foodjournal.application.VoiceTranscriber; import io.github.foodjournal.config.BotProperties; import java.util.*; import org.springframework.stereotype.Component; import org.springframework.web.client.RestClient;
@Component public class GeminiVoiceTranscriber implements VoiceTranscriber {
 private final RestClient telegram; private final RestClient gemini; private final BotProperties props;
 public GeminiVoiceTranscriber(RestClient.Builder b,BotProperties p){props=p;telegram=b.baseUrl("https://api.telegram.org").build();gemini=b.baseUrl("https://generativelanguage.googleapis.com/v1beta").build();}
 public String transcribe(String telegramFileId,String mimeType){if(telegramFileId==null||telegramFileId.isBlank())throw new IllegalArgumentException("Missing Telegram voice file ID");String key=System.getenv("GEMINI_API_KEY");if(key==null||key.isBlank())throw new IllegalStateException("Gemini is not configured");Map<?,?> file=telegram.get().uri(uri->uri.path("/bot{token}/getFile").queryParam("file_id",telegramFileId).build(props.telegramToken())).retrieve().body(Map.class);Object result=file==null?null:file.get("result");if(!(result instanceof Map<?,?> map)||!(map.get("file_path") instanceof String path))throw new IllegalStateException("Telegram file unavailable");byte[] bytes=telegram.get().uri("/file/bot{token}/{path}",props.telegramToken(),path).retrieve().body(byte[].class);try{if(bytes==null||bytes.length==0||bytes.length>20_000_000)throw new IllegalStateException("Invalid voice payload");Map<String,Object> body=Map.of("contents",List.of(Map.of("parts",List.of(Map.of("text","Transcribe this voice note exactly. Return only the transcript."),Map.of("inline_data",Map.of("mime_type",mimeType==null?"audio/ogg":mimeType,"data",Base64.getEncoder().encodeToString(bytes)))))));Map<?,?> response=gemini.post().uri("/models/gemini-2.0-flash:generateContent?key={key}",key).body(body).retrieve().body(Map.class);Object candidates=response==null?null:response.get("candidates");if(!(candidates instanceof List<?> list)||list.isEmpty())throw new IllegalStateException("Gemini transcript unavailable");Object content=((Map<?,?>)list.get(0)).get("content");Object parts=content instanceof Map<?,?> c?c.get("parts"):null;return parts instanceof List<?> listParts&&!listParts.isEmpty()?String.valueOf(((Map<?,?>)listParts.get(0)).get("text")).trim():"";}finally{if(bytes!=null)Arrays.fill(bytes,(byte)0);}}
}
